<?php
$month=$_GET['month'] ?? date('Y-m'); if (!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month)) $month=date('Y-m');
$date=new DateTimeImmutable($month.'-01',new DateTimeZone('UTC')); $days=(int)$date->format('t'); $offset=(int)$date->format('N')-1;
?>
<div class="panel"><div class="record-head"><h3><?= e($date->format('F Y')) ?></h3><div class="record-links"><a href="/dashboard?tab=viewings&month=<?= $date->modify('-1 month')->format('Y-m') ?>">Previous</a><a href="/dashboard?tab=viewings&month=<?= $date->modify('+1 month')->format('Y-m') ?>">Next</a></div></div><p class="tiny">Appointment calendar · UTC · cancelled appointments omitted</p><div class="appointment-calendar"><?php foreach (['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day): ?><span class="calendar-day-name"><?= $day ?></span><?php endforeach; for ($blank=0;$blank<$offset;$blank++): ?><div class="calendar-cell muted"></div><?php endfor; for ($day=1;$day<=$days;$day++): $ymd=$month.'-'.str_pad((string)$day,2,'0',STR_PAD_LEFT); ?><div class="calendar-cell <?= $ymd===date('Y-m-d')?'today':'' ?>"><strong><?= $day ?></strong><?php foreach ($data['viewings'] as $viewing): ?><?php if (substr($viewing['starts_at'],0,10)===$ymd && $viewing['status']!=='cancelled'): ?><a href="#viewing-<?= $viewing['id'] ?>"><?= e(substr($viewing['starts_at'],11,5)) ?> · <?= e($viewing['title']) ?></a><?php endif; endforeach ?></div><?php endfor ?></div></div>
